32	export function subscribe<K extends TaskflowEventType>(
33	  type: K,
34	  handler: EventHandler<K>,
35	): Unsubscribe {
36	  const set: HandlerSet = new Set(handlers.get(type));
37	  set.add(handler as EventHandler<TaskflowEventType>);
38	  handlers.set(type, set);
39	  return () => {
40	    set.delete(handler as EventHandler<TaskflowEventType>);
41	  };
